def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    nanos = nanoseconds % 1_000_000_000

    if tz is None:
        # Assuming LocalTime if no timezone is provided
        dt = datetime.fromtimestamp(seconds).replace(microsecond=0)
        dt += timedelta(microseconds=nanos // 1000)
        return dt.time().replace(microsecond=nanos // 1000)
    else:
        if not isinstance(tz, (timezone, str)):
            raise ValueError("tz must be a datetime.timezone or a string")
        if isinstance(tz, str):
            try:
                tz = timezone(timedelta(hours=int(tz)))
            except ValueError:
                raise ValueError("tz string must be in the format '+/-HH'")

        dt = datetime.fromtimestamp(seconds, tz).replace(microsecond=0)
        dt += timedelta(microseconds=nanos // 1000)
        return dt.time().replace(microsecond=nanos // 1000)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Value must be an instance of timedelta")

    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

