def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, '_data'):
        raise AttributeError("The record does not have a _data attribute.")

    if not keys:
        return list(self._data.values())

    result = []
    for key in keys:
        try:
            result.append(self._data[key])
        except KeyError:
            raise KeyError(f"Key {key} not found in the record.")
    return result

def data(self, *keys):
    result = {}
    if not keys:
        return dict(self.__dict__)
    for key in keys:
        if isinstance(key, int):
            if key >= len(self.__dict__) or key < 0:
                raise IndexError("Index out of bounds")
            result[list(self.__dict__.keys())[key]] = list(self.__dict__.values())[key]
        elif isinstance(key, str):
            result[key] = self.__dict__.get(key, None)
        else:
            raise TypeError("Keys must be integers or strings")
    return result

