def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    from itertools import islice
    from concurrent.futures import ThreadPoolExecutor, as_completed

    def run_command(command):
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=False)
        return result.returncode, result.stdout

    def chunked_iterable(iterable, size):
        it = iter(iterable)
        while True:
            chunk = list(islice(it, size))
            if not chunk:
                break
            yield chunk

    if not cmd:
        raise ValueError("Command cannot be empty")

    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1")

    command_chunks = chunked_iterable(varargs, _max_length // len(' '.join(cmd)))
    all_commands = [(' '.join(cmd) + ' ' + ' '.join(args)).split() for args in command_chunks]

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_command = {executor.submit(run_command, command): command for command in all_commands}
        results = []
        for future in as_completed(future_to_command):
            try:
                exit_code, output = future.result()
                results.append((exit_code, output))
            except Exception as e:
                return 1, str(e).encode()

    if all(code == 0 for code, _ in results):
        return 0, b'\n'.join(output for _, output in results)
    else:
        return 1, b'\n'.join(output for _, output in results)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    try:
        # Check if the command tuple is empty
        if not cmd:
            raise ValueError("The command tuple is empty")

        # Convert the command tuple to a list for mutability
        cmd_list = list(cmd)

        # Fix shebang issues on Windows by checking the first element
        if cmd_list[0].startswith('#!'):
            # Replace the shebang line with the appropriate Python executable
            cmd_list[0] = 'python'

        # Return the corrected command as a tuple
        return tuple(cmd_list)
    except Exception as e:
        # Handle any unexpected errors and return the original command
        print(f"An error occurred: {e}")
        return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                with lock:
                    if cache_key not in cache:
                        cache[cache_key] = func(*args, **kwargs)
                    return cache[cache_key]
            else:
                if cache_key not in cache:
                    cache[cache_key] = func(*args, **kwargs)
                return cache[cache_key]
        return wrapper
    return decorator

