def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with lock:
                    if k in cache:
                        return cache[k]
            except TypeError:
                # lock is None or not a context manager
                if k in cache:
                    return cache[k]
            result = func(*args, **kwargs)
            try:
                with lock:
                    cache[k] = result
            except TypeError:
                # lock is None or not a context manager
                cache[k] = result
            return result
        return wrapper
    return decorator

