def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track unique classes and a list to maintain order
        seen = set()
        minimal = []
        for cls in classes:
            # Check if the class or any of its ancestors are already in seen
            if cls not in seen and all(base not in seen for base in cls.__bases__):
                minimal.append(cls)
                seen.add(cls)
                # Add all subclasses to seen to avoid them later
                for subclass in cls.__subclasses__():
                    seen.add(subclass)
        return minimal
    except Exception as e:
        # Handle any unexpected errors gracefully
        print(f"An error occurred: {e}")
        return []

