def to_csv(self, separator=",", header=None):
    if not isinstance(separator, str):
        raise ValueError("Separator must be a string.")
    if header is not None and not isinstance(header, str):
        raise ValueError("Header must be a string or None.")

    lines = []
    if header is not None:
        lines.append(header)

    for point in self.points:
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError("Each point must be a tuple of (coordinates, values).")

        coordinates, values = point
        if isinstance(coordinates, tuple):
            coordinates_str = separator.join(map(str, coordinates))
        else:
            coordinates_str = str(coordinates)

        if isinstance(values, tuple):
            values_str = separator.join(map(str, values))
        else:
            values_str = str(values)

        line = separator.join([coordinates_str, values_str])
        lines.append(line)

    return "\n".join(lines) + "\n"

