def difference(d1, d2, level=-1):
    def _difference(a, b, current_level):
        if current_level == 0:
            return {}

        result = {}
        for key in a:
            if key not in b:
                result[key] = a[key]
            elif isinstance(a[key], dict) and isinstance(b[key], dict):
                sub_diff = _difference(a[key], b[key], current_level - 1 if current_level > 0 else -1)
                if sub_diff:
                    result[key] = sub_diff
            elif a[key] != b[key]:
                result[key] = a[key]
        return result

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")

    return _difference(d1, d2, level)

