def _validate_labels(labels):
    import re
    from collections.abc import Mapping

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__("\n".join(f"{k}: {v}" for k, v in messages))

    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')

    if not isinstance(labels, Mapping):
        raise ValidationError([{"labels": "expected a dictionary"}])

    errors = []

    for key, value in labels.items():
        try:
            key_str = str(key)
            if not key_regex.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

            value_str = str(value)
            if not value_regex.match(value_str):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})
        except TypeError as e:
            errors.append({str(key): str(e)})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {'apiVersion', 'kind', 'metadata'}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, False) for item in value if isinstance(item, dict)]
        else:
            observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise ValueError("All arguments must be lists.")

    for schema_item, response_item in zip(observer_schema, response):
        if isinstance(schema_item, dict) and isinstance(response_item, dict):
            # Assuming there's a corresponding function to handle dict updates
            update_last_applied_manifest_dict_from_resp(last_applied_manifest, schema_item, response_item)
        elif isinstance(schema_item, list) and isinstance(response_item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest, schema_item, response_item)
        else:
            for manifest_item in last_applied_manifest:
                if manifest_item.get('name') == response_item.get('name'):
                    manifest_item.update({key: response_item.get(key, manifest_item.get(key)) for key in schema_item})
                    break
            else:
                # If the item does not exist in last_applied_manifest, add it
                last_applied_manifest.append(response_item.copy())

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, sub_schema in observer_schema.items():
        if field not in last_applied_manifest:
            try:
                last_applied_manifest[field] = response[field]
            except KeyError:
                raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")
        if isinstance(sub_schema, dict) and isinstance(last_applied_manifest.get(field), dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response.get(field, {})
            )
        elif isinstance(sub_schema, list) and isinstance(last_applied_manifest.get(field), list):
            for i in range(max(len(last_applied_manifest[field]), len(response.get(field, [])))):
                item_schema = sub_schema[0] if sub_schema else {}
                last_applied_manifest[field].setdefault(i, {})
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field][i], item_schema, response.get(field, [{}])[i]
                )

