    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application object does not contain a valid spec.manifest")

        default_schema = {}
        for resource in app.spec.manifest:
            if 'kind' not in resource:
                raise ValueError("Resource in manifest does not contain a 'kind' field")

            kind = resource['kind']
            if kind not in app.observer_schema:
                default_schema[kind] = {
                    "metrics": [
                        {"name": "cpu_usage", "type": "resource"},
                        {"name": "memory_usage", "type": "resource"}
