def _explore_zipfile(zip_path):
    import os
    import zipfile
    import xml.etree.ElementTree as ET

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            file_list = z.namelist()
            data = {}

            for file in file_list:
                if file.endswith('.xml'):
                    with z.open(file) as f:
                        tree = ET.parse(f)
                        root = tree.getroot()
                        base_name = os.path.splitext(os.path.basename(file))[0]
                        if base_name not in data:
                            data[base_name] = []
                        data[base_name].append({file: root.tag})

        return data

    except FileNotFoundError:
        raise FileNotFoundError(f"The file at path {zip_path} does not exist.")
    except zipfile.BadZipFile:
        raise ValueError(f"The file at path {zip_path} is not a valid zip file.")
    except ET.ParseError:
        raise ValueError(f"The file at path {zip_path} contains invalid XML files.")
    except Exception as e:
        raise Exception(f"An error occurred while processing the zip file: {str(e)}")

