def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, tuple)) or not commands:
        raise ValueError("Commands must be a non-empty list or tuple.")
    if not isinstance(args, (list, tuple)):
        raise ValueError("Arguments must be a list or tuple.")
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("Current working directory must be a valid directory path.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment variables must be provided as a dictionary.")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, errors = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=output, stderr=errors)

        if verbose and output:
            print("Command output:\n", output)

        return output

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}:\n", e.output)
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

