    num_objects = 0
    good_objects = 0

    try:
        # Simulate traversal of storage root hierarchy
        for obj in self.storage_root.traverse():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.validate():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} is invalid")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj}")

            if is_valid:
                good_objects += 1

    except Exception as e:
