def validate_version_inventories(self, version_dirs):
    try:
        if not isinstance(version_dirs, list) or not all(isinstance(d, str) for d in version_dirs):
            raise ValueError("version_dirs must be a list of strings")

        root_inventory = self.load_inventory(version_dirs[0]) if version_dirs else {}
        content_digests = set(root_inventory.get('content_digests', []))
        discrepancies = []

        for version_dir in version_dirs[1:]:
            current_inventory = self.load_inventory(version_dir)
            current_digests = set(current_inventory.get('content_digests', []))

            if not current_inventory:
                discrepancies.append(f"Missing inventory for version: {version_dir}")
                continue

            missing_digests = content_digests - current_digests
            if missing_digests:
                discrepancies.append(f"Version {version_dir} is missing digests: {missing_digests}")

            content_digests.update(current_digests)

        return discrepancies

    except Exception as e:
        return [f"An error occurred while validating version inventories: {str(e)}"]

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'

        if not os.path.isdir(path):
            return 'Error: Path is not a file or directory'

        namaste_file_0 = os.path.join(path, '0=ocfl_1.0')
        namaste_file_0_root = os.path.join(path, '0=ocfl_1.0-storage_root')
        namaste_file_0_object = os.path.join(path, '0=ocfl_object_1.0')

        if os.path.isfile(namaste_file_0_root):
            return 'root'
        elif os.path.isfile(namaste_file_0_object):
            return 'object'
        elif os.path.isfile(namaste_file_0):
            return 'Error: Ambiguous OCFL version file'
        else:
            return 'Error: No OCFL Namaste file found'

    except Exception as e:
        return f'Error: {str(e)}'

