def deep_merge_nodes(nodes):
    def merge_values(key, value1, value2):
        if isinstance(value1, ruamel.yaml.nodes.MappingNode) and isinstance(value2, ruamel.yaml.nodes.MappingNode):
            merged_value = {}
            for k, v in value1.value:
                merged_value[k.value] = v
            for k, v in value2.value:
                merged_value[k.value] = v
            return ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=[(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=k), v) for k, v in merged_value.items()])
        else:
            return value2

    merged_nodes = {}
    for key, value in nodes:
        key_value = key.value
        if key_value in merged_nodes:
            merged_nodes[key_value] = merge_values(key, merged_nodes[key_value], value)
        else:
            merged_nodes[key_value] = value

    return [(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=k), v) for k, v in merged_nodes.items()]

