def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser 1: foo
    parser_foo = subparsers.add_parser('foo', help='foo subparser')
    parser_foo.add_argument('--foo-option', type=int, help='foo option help')

    # Example subparser 2: bar
    parser_bar = subparsers.add_parser('bar', help='bar subparser')
    parser_bar.add_argument('--bar-option', type=str, help='bar option help')

    # Global arguments
    parser.add_argument('--global-option', type=float, help='global option help')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit as e:
        return {}

    result = {}
    if args.subparser_name is None:
        result["global"] = argparse.Namespace(**vars(args))
    else:
        result[args.subparser_name] = argparse.Namespace(**vars(args))
        del result[args.subparser_name].subparser_name

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
