    for name, subparser in subparsers.items():
        try:
            parsed_namespace, remaining = subparser.parse_known_args(remaining_arguments)
            parsed_results[name] = parsed_namespace
            remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, we can choose to skip this subparser or raise an exception
            # Here we choose to skip and continue with other subparsers
            continue

    return parsed_results, remaining_arguments

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def merge_values(key, val1, val2):
        if isinstance(val1, MappingNode) and isinstance(val2, MappingNode):
            new_value = val1.value.copy()
            for k2, v2 in val2.value:
                found = False
                for i, (k1, v1) in enumerate(new_value):
                    if k1.value == k2.value:
                        new_value[i] = (k2, merge_values(k2, v1, v2))
                        found = True
                        break
                if not found:
                    new_value.append((k2, v2))
            return MappingNode(tag=val1.tag, value=new_value)
        else:
            return val2

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = merge_values(key_node, merged_dict[key], value_node)
        else:
            merged_dict[key] = value_node

    return [(ScalarNode(tag=key_node.tag, value=key), value) for key, value in merged_dict.items()]

