def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import argparse
        import borgmatic.commands.arguments
    except ImportError as e:
        return f"# Error: Required module not found: {e}"

    def generate_completion_script(parser, command=None):
        completion_script = []
        if command:
            completion_script.append(f"_borgmatic_{command}() {{")
            completion_script.append(f"    COMPREPLY=()")
            completion_script.append(f"    _parse_help $'$(borgmatic {command} --help)'")
            completion_script.append(f"}}")
        else:
            completion_script.append("_borgmatic() {")
            completion_script.append("    COMPREPLY=()")
            completion_script.append("    _parse_help $'$(borgmatic --help)'")
            completion_script.append("}")

        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subcommand, subparser in action.choices.items():
                    completion_script.extend(generate_completion_script(subparser, subcommand))
                break

        return completion_script

    try:
        main_parser = borgmatic.commands.arguments.make_parsers()[0]
        completion_script = generate_completion_script(main_parser)
        return "\n".join(completion_script)
    except Exception as e:
        return f"# Error generating bash completion script: {e}"

