def paging(response, max_results):
    if not isinstance(response, list):
        raise ValueError("The response must be a list.")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer.")

    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
    if size[-1].upper() in suffixes:
        value = size[:-1]
        suffix = size[-1].upper()
    else:
        value = size
        suffix = None

    try:
        numeric_value = float(value)
    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

    if suffix:
        return int(numeric_value * suffixes[suffix])
    else:
        return int(numeric_value)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements of the input iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All values in the dictionaries must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

