def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) for char in alphabet) or len(alphabet) < 2:
        raise ValueError("Alphabet must be a list of strings with at least two elements.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)

    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))
    if padding is not None:
        result = result.rjust(padding, alphabet[0])
    return result

