        # Process the output to extract ignored files
        files = result.stdout.splitlines()
        ignored_files = [file.split()[-1] for file in files if file.startswith('!!')]

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
