def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os

    if not callable(func):
        raise ValueError("The provided func must be a callable function.")

    func_module = func.__module__
    if func_module is None or func_module == str.__class__.__module__:
        raise ValueError("The function must be in an importable module.")

    func_name = func.__name__

    # Prepare the environment for the subprocess
    env = os.environ.copy()
    if extra_env is not None:
        if not isinstance(extra_env, dict):
            raise ValueError("extra_env must be a dictionary.")
        env.update(extra_env)

    # Prepare the command to run the function via subprocess
    command = [f"python -c 'import {func_module}; {func_module}.{func_name}(*{args})'"]

    try:
        result = subprocess.run(command, shell=True, timeout=timeout, env=env, capture_output=True, text=True)
        result.check_returncode()  # Raises CalledProcessError if the sub-process returns a non-zero exit code
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError("The subprocess exceeded the allowed time.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"The subprocess failed with error: {e.stderr}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {str(e)}")

def _resolve_string(matcher):
    if not isinstance(matcher, dict) or 'name' not in matcher:
        raise ValueError("Matcher must be a dictionary with a 'name' key.")

    name = matcher['name']
    default = matcher.get('default', None)

    value = os.getenv(name, default)

    if value is None:
        raise EnvironmentError(f"Environment variable '{name}' is not defined and no default value was provided.")

    return value

