def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
            raise ValueError("Commands must be a list of strings.")
        if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
            raise ValueError("Args must be a list of strings.")

        full_command = commands + args
        if verbose:
            print("Running command:", ' '.join(full_command))

        stderr_option = subprocess.DEVNULL if hide_stderr else None

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr_option
        )

        if verbose:
            if result.stdout:
                print("Standard Output:\n", result.stdout)
            if result.stderr and not hide_stderr:
                print("Standard Error:\n", result.stderr)

        result.check_returncode()  # Raises CalledProcessError if returncode is not 0
        return result.stdout, result.stderr

    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code:", e.returncode)
            print("Error output:\n", e.stderr)
        raise
    except Exception as e:
        if verbose:
            print("An error occurred:", e)
        raise

