) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        nodes_with_preds = {subj for subj, pred, obj in graph if pred == prop}
        nodes_with_objs = {obj for subj, pred, obj in graph if pred == prop}
        potential_roots = nodes_with_preds - nodes_with_objs
        roots.update(potential_roots)
        for root in potential_roots:
            find_roots(graph, prop, roots)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

