def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        coefficient = 1 / (sigma * np.sqrt(2 * np.pi))
        exponent = -((x - mu) ** 2) / (2 * sigma ** 2)
        return coefficient * np.exp(exponent)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except (FileNotFoundError, IOError) as e:
            log_records.append(logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'File not found or could not be read: {filename}',
                'exc_info': e
            }))
            continue
        except json.JSONDecodeError as e:
            log_records.append(logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'Failed to parse JSON in file: {filename}',
                'exc_info': e
            }))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[filename] = {**config, **overrides.get(filename, {})}

    return config_dict, log_records

