def scale(self, other=None, recompute=False):
    if other is None:
        if self._scale is None or recompute:
            self._scale = self._compute_scale()
        return self._scale
    else:
        if self._scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        self._scale = other
        # Rescale the histogram data based on the new scale
        scale_factor = other / self._scale
        self._data = [value * scale_factor for value in self._data]

def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise LenaValueError("Scale value must be a number.")
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        scale_factor = other / self._scale
        for i in range(len(self._data)):
            # Assuming _data is a list of tuples where the last element is the coordinate to be scaled
            data_tuple = list(self._data[i])
            data_tuple[-1] *= scale_factor
            # Rescale errors if they exist, assuming they are in the second to last position
            if len(data_tuple) > 2:
                data_tuple[-2] *= scale_factor
            self._data[i] = tuple(data_tuple)
        self._scale = other

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if not isinstance(field_names, tuple):
        raise TypeError("field_names must be a tuple")

    if scale is True:
        graph_scale = hist.scale
    elif scale is None:
        graph_scale = None
    else:
        graph_scale = scale

    graph_data = []
    for bin_index, bin_ in enumerate(hist.bins):
        if get_coordinate == "left":
            x = hist.bin_left_edges[bin_index]
        elif get_coordinate == "right":
            x = hist.bin_right_edges[bin_index]
        elif get_coordinate == "middle":
            x = (hist.bin_left_edges[bin_index] + hist.bin_right_edges[bin_index]) / 2

        try:
            value = make_value(bin_.content)
        except AttributeError:
            value = make_value(bin_)

        if not isinstance(value, tuple):
            value = (value,)

        point = (x,) + value
        if len(point) != len(field_names):
            raise ValueError("The number of values in make_value's result must match the number of field_names")

        graph_data.append(point)

    return {field: [point[i] for point in graph_data] for i, field in enumerate(field_names)}

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Interface, Invalid
    from inspect import signature
    from collections.abc import Callable

    errors = []

    if not isinstance(iface, Interface):
        errors.append(f"'{iface}' is not a valid Zope Interface.")

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface '{iface}'.")

    for name in iface.names():
        if name not in vars(candidate):
            if iface.get(name) is not None and not callable(iface.get(name)):
                errors.append(f"Missing attribute '{name}' in candidate.")
            else:
                errors.append(f"Missing method '{name}' in candidate.")

        if name in vars(candidate):
            if iface.get(name) and isinstance(iface.get(name), Callable):
                candidate_method = getattr(candidate, name)
                if not callable(candidate_method):
                    errors.append(f"'{name}' is supposed to be a method but is not callable in candidate.")
                else:
                    try:
                        candidate_sig = signature(candidate_method)
                        iface_sig = signature(iface[name])
                        if len(candidate_sig.parameters) != len(iface_sig.parameters):
                            errors.append(f"Method '{name}' has incorrect number of parameters in candidate.")
                        for (candidate_name, candidate_param), (iface_name, iface_param) in zip(candidate_sig.parameters.items(), iface_sig.parameters.items()):
                            if candidate_param.annotation != iface_param.annotation:
                                errors.append(f"Method '{name}' has incorrect parameter annotation for '{candidate_name}' in candidate.")
                    except ValueError as e:
                        errors.append(f"Error checking signature for method '{name}': {e}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    import zope.interface

    def _check_methods():
        errors = []
        for name in iface.names(all=True):
            if name.startswith('__') and name.endswith('__'):
                continue
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Not callable: {name}")
                else:
                    spec = iface.get(name, None)
                    if spec is not None:
                        try:
                            zope.interface.verify.verifyObjectMethod(spec, method)
                        except zope.interface.exceptions.BrokenMethodImplementation as e:
                            errors.append(str(e))
        return errors

    def _check_attributes():
        errors = []
        for name in iface.names(all=True):
            if name.startswith('__') and name.endswith('__'):
                continue
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")
        return errors

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    errors.extend(_check_methods())
    errors.extend(_check_attributes())

    if errors:
        if len(errors) == 1:
            raise zope.interface.exceptions.Invalid(errors[0])
        else:
            raise zope.interface.exceptions.Invalid('\n'.join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if not isinstance(iface, (type, tuple)):
