        return False

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc:
        return explicit_mc
    elif bases:
        metaclasses = {type(b) for b in bases}
        if not metaclasses:
            return type
        elif len(metaclasses) == 1:
            return metaclasses.pop()
        else:
            raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all the metaclasses of its bases")
    else:
        return type

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

