def isoparse(self, dt_str):
    from datetime import datetime
    from dateutil import parser, tz

    try:
        # Parse the ISO-8601 string into a datetime object
        dt = parser.isoparse(dt_str)

        # Handle the special case where the hour is 24
        if dt.hour == 24:
            dt = dt.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(days=1)

        # Ensure the timezone is properly set for UTC
        if dt.utcoffset() == datetime.timedelta(0):
            dt = dt.replace(tzinfo=tz.tzutc())

        return dt

    except ValueError as e:
        raise ValueError(f"Invalid ISO-8601 format: {e}")

