def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender_handle and entity_handle must be provided.")

    if not isinstance(sender_handle, str) or not isinstance(entity_handle, str):
        raise TypeError("Both sender_handle and entity_handle must be strings.")

    if sender_handle != entity_handle:
        raise ValueError("Sender handle and entity handle do not match.")

    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not isinstance(url, str) or not url.startswith(('http://', 'https://')):
            raise ValueError("Invalid URL provided")

        if document_path and not isinstance(document_path, str):
            raise ValueError("Invalid document_path provided")

        base_path = document_path if document_path else "/.well-known/nodeinfo"
        document = {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                    "href": f"{url}{base_path}/2.0.json"
                },
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "href": f"{url}{base_path}/2.0.json"
                },
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
                    "href": f"{url}{base_path}/2.1.json"
                }
            ]
        }
        return document

    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")

def verify_relayable_signature(public_key, doc, signature):
    try:
        from xml.crypto import ds  # Assuming xml.crypto.ds is used for signature verification
        sig = ds.Signature()
        sig.load(signature)
        sig.setPublicKey(public_key)
        return sig.verify(doc)
    except Exception as e:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON first
        data = json.loads(document)
        if isinstance(data, dict) and "subject" in data:
            return data
    except json.JSONDecodeError:
        pass

    try:
        # If JSON parsing fails, try to parse as XML
        root = ET.fromstring(document)
        if root.tag.endswith('XRD'):
            data = {}
            for elem in root:
                if elem.tag.endswith('Subject'):
                    data['subject'] = elem.text
                elif elem.tag.endswith('Alias'):
                    data.setdefault('aliases', []).append(elem.text)
            if 'subject' in data:
                return data
    except ET.ParseError:
        pass

    raise ValueError("Document is not a valid Diaspora webfinger JSON or XRD")

