def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests

    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "delete":
            response = requests.delete(url, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, timeout=timeout, *args, **kwargs)
        else:
            return None, ValueError(f"Unsupported HTTP method: {method}")

        return response.status_code, None
    except requests.exceptions.RequestException as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    try:
        current = dic
        for k in (key,) + keys[:-1]:
            if k not in current:
                current[k] = {}
            current = current[k]
        current[keys[-1]] = val
    except TypeError:
        raise ValueError("All keys must be hashable types")

def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names based on the given directories and specification option.

    Parameters:
    settings_dirs (list of str): List of directory paths to search for files.
    spec_option (str): Specification option to filter files (e.g., file extension).

    Returns:
    list of str: List of file names that match the specification option.
    """
    import os

    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list of directory paths.")
    if not all(isinstance(d, str) for d in settings_dirs):
        raise ValueError("Each element in settings_dirs must be a string representing a directory path.")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string representing the specification option.")

    file_names = []
    for directory in settings_dirs:
        try:
            if os.path.isdir(directory):
                for entry in os.listdir(directory):
                    if spec_option in entry:
                        file_names.append(entry)
        except Exception as e:
            print(f"An error occurred while processing directory '{directory}': {e}")

    return file_names

