def validate_from_file(cls, yaml_file=None):
    import yaml
    from pathlib import Path

    if not yaml_file or not isinstance(yaml_file, str):
        raise ValueError("yaml_file must be a valid string path")

    yaml_path = Path(yaml_file)
    if not yaml_path.exists() or not yaml_path.is_file():
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_path, 'r') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error loading YAML file: {e}")

    required_fields = {'name', 'version', 'description'}  # Example required fields
    missing_fields = required_fields - set(data.keys())
    if missing_fields:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    try:
        if not isinstance(parser_dict, dict):
            raise ValueError("Expected a dictionary as parser_dict")

        if 'include' not in parser_dict:
            return parser_dict

        include_directive = parser_dict['include']

        if not isinstance(include_directive, list):
            raise ValueError("Expected a list within the 'include' key")

        resolved_dict = parser_dict.copy()
        del resolved_dict['include']

        for entry in include_directive:
            if not isinstance(entry, dict):
                raise ValueError("Expected each include entry to be a dictionary")
            resolved_dict.update(entry)

        return resolved_dict

    except Exception as e:
        raise RuntimeError(f"Error processing include directive: {e}")

