def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary with length specifications.")

    for arg_name, (value, max_length) in args.items():
        if not isinstance(value, str):
            raise ValueError(f"The value for {arg_name} must be a string.")
        if not isinstance(max_length, int):
            raise ValueError(f"The maximum length for {arg_name} must be an integer.")
